package com.arjunren.bus;
import io.javalin.Javalin;import io.javalin.http.*;import java.math.BigDecimal;import java.sql.*;import java.time.*;import java.util.*;
public final class Main{public static void main(String[]args){var db=new Database(System.getenv().getOrDefault("DB_URL","jdbc:h2:file:./data/bus;AUTO_SERVER=TRUE"));db.migrate();var passwords=new PasswordService();seed(db,passwords);var auth=new AuthService(db,passwords);var bookings=new BookingService(db);var app=Javalin.create(config->{config.http.defaultContentType="application/json";config.bundledPlugins.enableCors(cors->cors.addRule(r->r.allowHost(System.getenv().getOrDefault("CORS_ORIGIN","http://localhost:3000"))));var routes=config.routes;
routes.exception(SecurityException.class,(e,c)->c.status("Forbidden".equals(e.getMessage())?403:401).json(error("AUTH_ERROR",e.getMessage())));routes.exception(IllegalArgumentException.class,(e,c)->c.status(400).json(error("VALIDATION_ERROR",e.getMessage())));routes.exception(IllegalStateException.class,(e,c)->c.status(409).json(error("CONFLICT",e.getMessage())));
routes.post("/api/auth/login",c->{var x=c.bodyAsClass(Login.class);var s=auth.login(x.username(),x.password());c.json(Map.of("data",s));});routes.post("/api/auth/logout",c->{auth.require(c.header("Authorization"));auth.logout(c.header("Authorization"));c.status(204);});
routes.get("/api/trips",c->{auth.require(c.header("Authorization"));try(var cn=db.connection();var s=cn.prepareStatement("SELECT t.id,b.name,r.origin,r.destination,r.base_fare,t.departure_at,t.status,b.capacity FROM trips t JOIN buses b ON b.id=t.bus_id JOIN routes r ON r.id=t.route_id ORDER BY t.departure_at")){c.json(Map.of("data",rows(s)));}});
routes.post("/api/buses",c->{auth.require(c.header("Authorization"),"ADMIN");var x=c.bodyAsClass(BusInput.class);if(x.capacity()<1)throw new IllegalArgumentException("Capacity must be positive");try(var cn=db.connection();var s=cn.prepareStatement("INSERT INTO buses(plate_number,name,capacity) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,x.plateNumber());s.setString(2,x.name());s.setInt(3,x.capacity());s.executeUpdate();c.status(201).json(Map.of("data",Map.of("plateNumber",x.plateNumber())));}});
routes.post("/api/routes",c->{auth.require(c.header("Authorization"),"ADMIN");var x=c.bodyAsClass(RouteInput.class);if(x.baseFare().signum()<=0)throw new IllegalArgumentException("Fare must be positive");try(var cn=db.connection();var s=cn.prepareStatement("INSERT INTO routes(origin,destination,base_fare) VALUES(?,?,?)")){s.setString(1,x.origin());s.setString(2,x.destination());s.setBigDecimal(3,x.baseFare());s.executeUpdate();c.status(201).json(Map.of("data",x));}});
routes.post("/api/trips",c->{auth.require(c.header("Authorization"),"ADMIN");var x=c.bodyAsClass(TripInput.class);if(x.departureAt().isBefore(OffsetDateTime.now()))throw new IllegalArgumentException("Departure must be in the future");try(var cn=db.connection();var s=cn.prepareStatement("INSERT INTO trips(bus_id,route_id,departure_at) VALUES(?,?,?)")){s.setLong(1,x.busId());s.setLong(2,x.routeId());s.setObject(3,x.departureAt());s.executeUpdate();c.status(201).json(Map.of("data",x));}});
routes.post("/api/bookings",c->{var p=auth.require(c.header("Authorization"),"ADMIN","PASSENGER");var x=c.bodyAsClass(BookingInput.class);c.status(201).json(Map.of("data",bookings.reserve(p.userId(),x.tripId(),x.seatNumber())));});
routes.get("/api/bookings",c->{var p=auth.require(c.header("Authorization"),"ADMIN","PASSENGER");var sql="SELECT id,reference,trip_id,user_id,seat_number,status,fare,created_at FROM bookings"+("ADMIN".equals(p.role())?"":" WHERE user_id=?")+" ORDER BY created_at DESC";try(var cn=db.connection();var s=cn.prepareStatement(sql)){if(!"ADMIN".equals(p.role()))s.setLong(1,p.userId());c.json(Map.of("data",rows(s)));}});
routes.patch("/api/bookings/{id}/cancel",c->{var p=auth.require(c.header("Authorization"),"ADMIN","PASSENGER");bookings.cancel(Long.parseLong(c.pathParam("id")),p.userId(),"ADMIN".equals(p.role()));c.json(Map.of("data",Map.of("status","CANCELLED")));});
routes.get("/api/dashboard",c->{auth.require(c.header("Authorization"),"ADMIN");try(var cn=db.connection();var s=cn.prepareStatement("SELECT COUNT(*) bookings,COALESCE(SUM(fare),0) revenue FROM bookings WHERE status='BOOKED'")){c.json(Map.of("data",rows(s).getFirst()));}});});app.start(Integer.parseInt(System.getenv().getOrDefault("PORT","8080")));}
static List<Map<String,Object>> rows(PreparedStatement s)throws SQLException{try(var r=s.executeQuery()){var out=new ArrayList<Map<String,Object>>();var m=r.getMetaData();while(r.next()){var row=new LinkedHashMap<String,Object>();for(int i=1;i<=m.getColumnCount();i++)row.put(m.getColumnLabel(i).toLowerCase(),r.getObject(i));out.add(row);}return out;}}
static Map<String,Object> error(String code,String message){return Map.of("error",Map.of("code",code,"message",message));}static void seed(Database db,PasswordService p){try(var c=db.connection()){if(count(c,"users")==0){try(var s=c.prepareStatement("INSERT INTO users(username,password_hash,role) VALUES(?,?,?)")){for(var u:new String[][]{{"admin","ADMIN"},{"passenger","PASSENGER"}}){s.setString(1,u[0]);s.setString(2,p.hash("ChangeMe123!"));s.setString(3,u[1]);s.addBatch();}s.executeBatch();}c.createStatement().execute("INSERT INTO buses(plate_number,name,capacity) VALUES('DEMO-001','Demo Coach',40)");c.createStatement().execute("INSERT INTO routes(origin,destination,base_fare) VALUES('Taipei','Taichung',25.00)");c.createStatement().execute("INSERT INTO trips(bus_id,route_id,departure_at) VALUES(1,1,DATEADD('DAY',7,CURRENT_TIMESTAMP))");}}catch(SQLException e){throw new IllegalStateException(e);}}static long count(Connection c,String table)throws SQLException{try(var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
public record Login(String username,String password){}public record BusInput(String plateNumber,String name,int capacity){}public record RouteInput(String origin,String destination,BigDecimal baseFare){}public record TripInput(long busId,long routeId,OffsetDateTime departureAt){}public record BookingInput(long tripId,int seatNumber){}}
